  archives: { resource: 'archive', title: '归档管理', description: '查看版本化归档' },
}[panel.value] || { resource: '', title: '社会实践', description: '' }));
const selectFilters = computed(() => [{ key: 'grade_id', label: '年级', options: state.options.grades.map(item => ({ value: item.grade_id, label: item.grade_name })) }, { key: 'dep_id', label: '学院', options: state.options.departments.map(item => ({ value: item.dep_id, label: item.dep_name })) }, { key: 'profession_id', label: '专业', options: state.options.professions.filter(item => !state.filters.dep_id || Number(item.dep_id) === Number(state.filters.dep_id)).map(item => ({ value: item.profession_id, label: item.profession_name })) }, { key: 'class_id', label: '班级', options: state.options.classes.filter(item => !state.filters.profession_id || Number(item.profession_id) === Number(state.filters.profession_id)).map(item => ({ value: item.class_id, label: item.class_name })) }]);
const statusOptions = computed(() => [{ value: 'draft', label: '草稿' }, { value: 'wait', label: '待审核' }, { value: 'accept', label: '已通过' }, { value: 'modify', label: '需修改' }, { value: 'enabled', label: '正常' }, { value: 'active', label: '进行中' }, { value: 'archived', label: '已归档' }]);
const overviewCards = [{ key: 'active_plans', label: '进行中计划' }, { key: 'active_participants', label: '参与学生' }, { key: 'pending_materials', label: '待审材料' }, { key: 'pending_scores', label: '待审成绩' }];
const currentPlans = computed(() => Array.isArray(state.overview.current_plans) ? state.overview.current_plans : []);
const overviewHint = computed(() => isStudent.value ? '查看自己的申报、材料和成绩' : isTeacher.value ? '优先处理指导学生的待办' : '掌握全校社会实践进度');
const canLoadMore = computed(() => state.rows.length < Number(state.pagination.total || 0));
const canCreate = computed(() => (panelMeta.value.resource === 'declaration' && isStudent.value && props.hasPermission('social_practice:declare')) || (['material', 'safety'].includes(panelMeta.value.resource) && (isStudent.value || isTeacher.value || isAdmin.value) && props.hasPermission('social_practice:material:manage')) || (panelMeta.value.resource === 'patch_sign' && isStudent.value && props.hasPermission('social_practice:attendance:manage')) || (panelMeta.value.resource === 'score' && (isTeacher.value || isAdmin.value) && props.hasPermission('social_practice:score:manage')) || (panelMeta.value.resource === 'plan' && isAdmin.value && props.hasPermission('social_practice:plan:manage')) || (panelMeta.value.resource === 'project' && isAdmin.value && props.hasPermission('social_practice:project:manage')) || (panelMeta.value.resource === 'implementation' && (isTeacher.value || isAdmin.value) && props.hasPermission('social_practice:project:manage')));
const createLabel = computed(() => ({ plan: '新增计划', project: '新增项目', implementation: '提交实施申请', declaration: '发起申报', safety: '提交安全材料', material: '提交成果材料', patch_sign: '申请补签', score: '录入成绩' }[panelMeta.value.resource] || '新增'));
const detailFacts = computed(() => ['title', 'plan_title', 'project_title', 'grade_name', 'student_name', 'applicant_name', 'teacher_name', 'assigned_teacher_name', 'location', 'declaration_type', 'teacher_confirm_status', 'date', 'sign_time', 'sign_date', 'final_score', 'version', 'status', 'created_at', 'updated_at'].map(key => ({ label: factLabel(key), value: ['status', 'teacher_confirm_status'].includes(key) ? statusText(state.detail[key]) : state.detail[key] })).filter(item => item.value !== undefined && item.value !== null && item.value !== ''));
const scoreDetailItems = computed(() => { const rules = new Map((state.detail.rules || []).map(item => [String(item.item_code), item])); return (state.detail.details || []).map(item => ({ ...item, item_name: rules.get(String(item.item_code))?.item_name || item.item_code, weight: Number(item.weight || rules.get(String(item.item_code))?.weight || 0), score_value: Number(item.score_value || 0) })); });
const reviewMin = computed(() => state.review.status === 'modify' ? 8 : 0);
const reviewMax = computed(() => state.review.status === 'modify' ? 800 : 300);
const formCanChooseTeacher = computed(() => {
  const plan = state.options.plans.find(item => Number(item.id) === Number(state.form.plan_id));
  return !plan || plan.teacher_match_mode !== 'admin_assign';
});
const geoStatusText = computed(() => ({ locating: '正在读取当前位置', ready: '已获取当前位置', denied: '无法获取位置', idle: '等待获取当前位置' }[state.geo.status] || '等待获取当前位置'));

watch(panel, () => { if (panel.value === 'overview') loadOverview(); else loadList(); }, { immediate: true });

/** 读取社会实践选项。 */
async function ensureOptions() { if (state.options.loaded) return; state.options = { ...emptyOptions(), ...(await fetchSocialPracticeOptions()), loaded: true }; if (!state.filters.grade_id) state.filters.grade_id = state.options.current_grade_id || ''; }
/** 读取社会实践总览。 */
async function loadOverview() { state.loading = true; state.message = ''; try { state.overview = (await fetchSocialPracticeOverview()).statistics || {}; } catch (error) { state.message = error.message; } finally { state.loading = false; } }
/** 读取当前 H5 列表。 */
async function loadList(page = 1, append = false) { state.loading = true; state.message = ''; try { await ensureOptions(); const data = await fetchSocialPracticeList(panelMeta.value.resource, { ...state.filters, page, page_size: state.pagination.page_size, practice_mode: panel.value === 'projects' ? 'centralized' : undefined }); const pagination = data.pagination || data; state.rows = append ? [...state.rows, ...(data.items || [])] : (data.items || []); state.pagination = { page: Number(pagination.page || page), page_size: Number(pagination.page_size || 10), total: Number(pagination.total || 0) }; } catch (error) { state.message = error.message; } finally { state.loading = false; } }
/** 加载更多列表。 */
function loadMore() { if (canLoadMore.value) loadList(state.pagination.page + 1, true); }
/** 更新筛选并执行查询。 */
function updateFilter({ key, value }) { state.filters[key] = value || ''; if (key === 'dep_id') { state.filters.profession_id = ''; state.filters.class_id = ''; } if (key === 'profession_id') state.filters.class_id = ''; loadList(); }
/** 恢复筛选条件。 */
function resetFilters() { state.filters = { grade_id: state.options.current_grade_id || '', dep_id: '', profession_id: '', class_id: '', status: '', keyword: '' }; loadList(); }
/** 打开当前记录详情。 */
async function openDetail(row) { state.loading = true; try { const resource = actionResource(row); state.detail = workflowResources.includes(resource) ? await fetchSocialPracticeDetail(resource, row.id) : { ...row }; state.dialog = { visible: true, type: 'detail', title: `${panelMeta.value.title}详情`, description: '' }; } catch (error) { showToast(error.message); } finally { state.loading = false; } }
/** 处理列表操作。 */
async function handleAction(action, row) { if (action.key === 'view') return openDetail(row); if (action.key === 'timeline') return openTimeline(row); if (action.key === 'review' || action.key === 'modify') return openReview(row, action.key); if (action.key === 'teacherConfirm') return openTeacherConfirm(row); if (action.key === 'teacherReselect') return openTeacherReselect(row); if (action.key === 'signIn') return openSignIn(row); if (action.key === 'assignTeacher') return openTeacherAssignment(row); if (action.key === 'edit' || action.key === 'create') return openForm(row); if (action.key === 'submit') return confirmSubmit(row); }
/** 打开业务表单。 */
async function openForm(row = null) { await ensureOptions(); let resource = panelMeta.value.resource; if (['safety', 'materials'].includes(panel.value)) resource = 'material'; let detail = row || {}; if (row && workflowResources.includes(resource)) detail = await fetchSocialPracticeDetail(resource, row.id); state.form = formFromRow(resource, detail); if (!row) applyPlanScopeDefaults(state.form); if (resource === 'material' && panel.value === 'safety' && !row) state.form.material_type = 'safety_agreement'; if (resource === 'material' && !state.form.student_id && isStudent.value) state.form.student_id = state.options.current_student_id || ''; if (resource === 'declaration' && state.form.plan_id) await loadPlanStudents(); if (resource === 'score' && state.form.project_id) await prepareScoreRules(state.form.project_id); state.dialog = { visible: true, type: 'form', title: row ? `编辑${panelMeta.value.title}` : createLabel.value, description: '可以先保存草稿，提交审核后才会进入审核列表' }; }
/** 读取当前计划可选择的团队成员。 */
async function loadPlanStudents() { if (!state.form.plan_id) { state.planStudents = []; return; } try { const data = await fetchSocialPracticeEligibleStudents(state.form.plan_id); state.planStudents = (data.items || []).filter(item => Number(item.student_id) !== Number(state.options.current_student_id || 0)); } catch (error) { state.planStudents = []; showToast(error.message); } }
/** 应用管理员默认组织范围。 */
function applyPlanScopeDefaults(form) { if (form.resource !== 'plan') return; const professionId = Number(state.options.default_profession_id || 0); const profession = state.options.professions.find(item => Number(item.profession_id) === professionId); const depId = Number(state.options.default_dep_id || profession?.dep_id || 0); if (professionId) { form.organizer_dep_id = depId || ''; form.scopes = [{ scope_type: 'profession', dep_id: depId || '', profession_id: professionId, class_id: '' }]; } else if (depId) { form.organizer_dep_id = depId; form.scopes = [{ scope_type: 'college', dep_id: depId, profession_id: '', class_id: '' }]; } form.approval_flow_id = state.options.approval_flows[0]?.id || ''; }
/** 打开当前面板的新建表单。 */
function openCreate() { openForm(); }
/** 保存表单草稿或提交审核。 */
async function saveForm(submit) { if (state.saving || state.uploading) return; state.saving = true; try { const payload = normalizeFormPayload(state.form); let result; if (state.form.resource === 'material') result = await saveSocialPracticeMaterial({ ...payload, submit }); else if (state.form.resource === 'patch_sign') result = await saveSocialPracticePatchSign({ ...payload, submit }); else if (state.form.resource === 'score') result = await saveSocialPracticeScore({ ...payload, submit }); else { result = await saveSocialPractice(payload); if (submit && state.form.resource !== 'project') await submitSocialPractice({ resource: state.form.resource, id: result.id }); } showToast(state.form.resource === 'project' ? '项目已保存' : (submit ? '已提交审核' : '草稿已保存')); closeDialog(true); await loadList(1); } catch (error) { showToast(error.message); } finally { state.saving = false; } }
/** 上传社会实践材料附件。 */
async function uploadMaterialFiles(event) { const files = Array.from(event.target.files || []); if (!files.length || state.uploading) return; state.uploading = true; try { for (const file of files) { const uploaded = await uploadFile(file, { category: 'social_practice_material', is_temporary: 'false' }); if (!state.form.attachments.some(item => Number(item.id || item.file_id) === Number(uploaded.file_id))) state.form.attachments.push({ id: uploaded.file_id, file_id: uploaded.file_id, name: uploaded.name || file.name, url: uploaded.url || '' }); } } catch (error) { showToast(error.message); } finally { state.uploading = false; event.target.value = ''; } }
/** 移除社会实践材料附件。 */
function removeMaterialFile(file) { const fileId = Number(file.id || file.file_id); state.form.attachments = state.form.attachments.filter(item => Number(item.id || item.file_id) !== fileId); }
/** 提交审核结果。 */
async function submitReview() { if (state.saving) return; if (state.review.opinion.length < reviewMin.value) { showToast(`意见至少填写 ${reviewMin.value} 字`); return; } state.saving = true; try { const resource = state.dialog.resource || actionResource(state.detail); const payload = { resource, id: state.detail.id, ...state.review }; if (state.dialog.type === 'modify') await requestSocialPracticeModification(payload); else await reviewSocialPractice(payload); showToast(state.dialog.type === 'modify' ? '已发起修改' : '审核已提交'); closeDialog(true); await loadList(state.pagination.page); } catch (error) { showToast(error.message); } finally { state.saving = false; } }
/** 打开流程记录时间线。 */
async function openTimeline(row) { state.loading = true; try { const resource = actionResource(row); state.timeline = await fetchSocialPracticeTimeline(resource, row.id); state.dialog = { visible: true, type: 'timeline', title: '流程记录', description: '按提交批次查看业务内容和审核支线', resource }; } catch (error) { showToast(error.message); } finally { state.loading = false; } }
/** 打开审核或通过后修改表单。 */
async function openReview(row, type) { const resource = actionResource(row); state.detail = { ...row }; state.review = { status: type === 'modify' ? 'modify' : 'accept', opinion: '' }; if (type === 'review') { try { const data = await fetchSocialPracticeReviewDraft(resource, row.id); if (data?.draft) state.review = { status: data.draft.review_status || 'accept', opinion: data.draft.opinion || '' }; } catch (error) { if (error?.status !== 404) showToast(error.message); } } state.dialog = { visible: true, type, title: type === 'modify' ? '通过后修改' : `审核${panelMeta.value.title}`, description: '提交后会写入审核记录并通知相关人员', resource }; }
/** 打开指导教师确认。 */
function openTeacherConfirm(row) { state.detail = { ...row }; state.review = { status: 'accepted', opinion: '' }; state.dialog = { visible: true, type: 'teacherConfirm', title: '确认指导教师身份', description: '确认后将进入申报审核流程', resource: 'declaration' }; }
/** 读取浏览器 GPS 并打开签到窗口。 */
function openSignIn(row) { state.detail = { ...row }; state.geo = { status: 'locating', project_id: row.id, latitude: '', longitude: '', accuracy: '', location: row.location || '', remark: '' }; state.dialog = { visible: true, type: 'signIn', title: 'GPS 签到', description: '位置由浏览器定位获取，不能手动修改' }; if (!navigator.geolocation) { state.geo.status = 'denied'; return; } navigator.geolocation.getCurrentPosition((position) => { state.geo.status = 'ready'; state.geo.latitude = position.coords.latitude.toFixed(7); state.geo.longitude = position.coords.longitude.toFixed(7); state.geo.accuracy = Math.round(position.coords.accuracy || 0); }, () => { state.geo.status = 'denied'; }, { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }); }
/** 提交 GPS 签到。 */
async function submitSignIn() { if (state.saving) return; if (state.geo.status !== 'ready') { showToast('尚未获取到有效位置'); return; } state.saving = true; try { await saveSocialPracticeSignIn({ project_id: state.geo.project_id || state.detail.id, date: new Date().toISOString().slice(0, 10), longitude: Number(state.geo.longitude), latitude: Number(state.geo.latitude), location: state.geo.location, remark: state.geo.remark }); showToast('签到成功'); closeDialog(true); if (panel.value === 'attendance') await loadList(1); } catch (error) { showToast(error.message); } finally { state.saving = false; } }
/** 打开管理员分配指导教师窗口。 */
function openTeacherAssignment(row) { state.assignment = { declaration_id: row.id, teacher_id: row.assigned_teacher_id || row.selected_teacher_id || '' }; state.dialog = { visible: true, type: 'assignTeacher', title: '分配分散实践指导教师', description: '分配后教师需要在确认期限内处理', resource: 'declaration' }; }
/** 保存管理员分配的指导教师。 */
async function submitTeacherAssignment() { if (state.saving) return; if (!state.assignment.teacher_id) { showToast('请选择指导教师'); return; } state.saving = true; try { await assignSocialPracticeDeclarationTeacher({ declaration_id: state.assignment.declaration_id, teacher_id: state.assignment.teacher_id }); showToast('指导教师已分配'); closeDialog(true); await loadList(1); } catch (error) { showToast(error.message); } finally { state.saving = false; } }
/** 打开学生重新选择指导教师窗口。 */
function openTeacherReselect(row) { state.reselect = { declaration_id: row.id, teacher_id: '' }; state.dialog = { visible: true, type: 'teacherReselect', title: '重新选择指导教师', description: '提交后会重新发送教师确认待办', resource: 'declaration' }; }
/** 提交学生重新选择的指导教师。 */
async function submitTeacherReselect() { if (state.saving) return; if (!state.reselect.teacher_id) { showToast('请选择指导教师'); return; } state.saving = true; try { await reselectSocialPracticeTeacher({ declaration_id: state.reselect.declaration_id, teacher_id: state.reselect.teacher_id }); showToast('已重新选择指导教师'); closeDialog(true); await loadList(1); } catch (error) { showToast(error.message); } finally { state.saving = false; } }
/** 保存审核意见草稿。 */
async function saveReviewDraftOnly() { if (state.saving) return; state.saving = true; try { await saveSocialPracticeReviewDraft({ resource: state.dialog.resource || actionResource(state.detail), id: state.detail.id, ...state.review }); showToast('审核草稿已保存'); } catch (error) { showToast(error.message); } finally { state.saving = false; } }
/** 提交成员或教师确认。 */
async function submitConfirmation() { if (state.saving) return; state.saving = true; try { if (state.dialog.type === 'teacherConfirm') await confirmSocialPracticeTeacher({ declaration_id: state.detail.id, status: state.review.status }); else await confirmSocialPracticeMember({ declaration_id: state.confirmation.declaration_id, student_id: state.confirmation.student_id, status: state.confirmation.status }); showToast('确认已保存'); closeDialog(true); await loadList(1); } catch (error) { showToast(error.message); } finally { state.saving = false; } }
/** 确认团队成员加入或拒绝。 */
async function confirmMember(member, status) { try { await showConfirmDialog({ title: status === 'accepted' ? '确认加入团队' : '拒绝加入团队', message: status === 'accepted' ? '确认后将作为有效团队成员参与实践。' : '拒绝后本次申报不会把你加入项目。' }); state.saving = true; await confirmSocialPracticeMember({ declaration_id: state.detail.id, student_id: member.student_id, status }); showToast('成员确认已保存'); const detail = await fetchSocialPracticeDetail('declaration', state.detail.id); state.detail = detail; } catch (error) { if (!['cancel', 'close'].includes(error)) showToast(error.message || String(error)); } finally { state.saving = false; } }
/** 判断当前学生能否确认指定团队成员。 */
function canConfirmMember(member) { return isStudent.value && Number(member.student_id) === Number(state.options.current_student_id || 0); }
/** 确认指导教师接受或拒绝申报。 */
async function confirmTeacher(status) { state.review.status = status; await submitConfirmation(); }
/** 关闭当前弹窗并清理临时状态。 */
function closeDialog(force = false) { if (state.saving && !force) return; state.dialog = { visible: false, type: '', title: '', description: '', resource: '' }; state.detail = {}; state.timeline = { records: [], reviews: [] }; }
/** 读取指定资源的编辑权限。 */
function canEditResource(resource) { if (resource === 'plan') return isAdmin.value && props.hasPermission('social_practice:plan:manage'); if (resource === 'project') return isAdmin.value && props.hasPermission('social_practice:project:manage'); if (resource === 'implementation') return (isTeacher.value || isAdmin.value) && props.hasPermission('social_practice:project:manage'); if (resource === 'declaration') return isStudent.value && props.hasPermission('social_practice:declare'); if (resource === 'material') return (isStudent.value || isTeacher.value || isAdmin.value) && props.hasPermission('social_practice:material:manage'); if (resource === 'patch_sign') return isStudent.value && props.hasPermission('social_practice:attendance:manage'); if (resource === 'score') return (isTeacher.value || isAdmin.value) && props.hasPermission('social_practice:score:manage'); return false; }
/** 读取指定资源的审核权限。 */
function canReviewResource(resource) { return resource === 'score' ? props.hasPermission('social_practice:score:approve') : props.hasPermission('social_practice:approve'); }
/** 返回当前行对应资源。 */
function actionResource(row) { return row.resource || (panelMeta.value.resource === 'safety' ? 'material' : panelMeta.value.resource); }
/** 准备成绩评分项。 */
async function prepareScoreRules(projectId) { const project = state.options.projects.find(item => Number(item.id) === Number(projectId)); if (!project) return; try { const plan = await fetchSocialPracticeDetail('plan', project.plan_id); const existing = new Map((state.form.details || []).map(item => [String(item.item_code), item])); state.form.items = (plan.score_rules || []).filter(item => item.practice_mode === project.practice_mode).map(item => ({ ...item, score_value: Number(existing.get(String(item.item_code))?.score_value || 0) })); } catch (error) { showToast(error.message); } }
/** 将详情记录转换为可编辑表单。 */
function formFromRow(resource, row) { const form = { ...emptyForm(resource) }; Object.keys(form).forEach(key => { if (row?.[key] !== undefined && row?.[key] !== null) form[key] = row[key]; }); if (resource === 'plan') { form.scopes = (row?.scopes || form.scopes).map(item => ({ ...item })); form.requirements = (row?.requirements || form.requirements).map(item => ({ ...item, required_flag: item.required_flag === true || item.required_flag === 'true' })); form.score_rules = (row?.score_rules || form.score_rules).map(item => ({ ...item, weight: Number(item.weight || 0), max_score: Number(item.max_score || 100) })); } if (resource === 'declaration') form.member_student_ids = (row?.members || []).map(item => item.student_id); if (resource === 'material') form.attachments = (row?.attachments || []).map(item => ({ ...item, file_id: item.file_id || item.id })); if (resource === 'score') form.details = row?.details || []; return normalizeDateFields(form); }
/** 规范化日期和附件字段。 */
function normalizeFormPayload(form) { const payload = JSON.parse(JSON.stringify(form)); ['register_start_at', 'register_end_at', 'practice_start_at', 'practice_end_at', 'result_deadline_at', 'score_deadline_at', 'start_at', 'end_at'].forEach(field => { if (payload[field]) payload[field] = String(payload[field]).replace('T', ' ') + (String(payload[field]).length === 16 ? ':00' : ''); }); if (payload.resource === 'material') payload.file_ids = (payload.attachments || []).map(item => item.file_id || item.id).filter(Boolean); delete payload.attachments; delete payload.details; return payload; }
/** 将服务端日期转为日期输入框格式。 */
function normalizeDateFields(form) { ['register_start_at', 'register_end_at', 'practice_start_at', 'practice_end_at', 'result_deadline_at', 'score_deadline_at', 'start_at', 'end_at'].forEach(field => { if (form[field]) form[field] = String(form[field]).slice(0, 16).replace(' ', 'T'); }); return form; }
/** 读取流程动作中文名。 */
function actionText(action) { return { submit: '提交审核', review: '审核处理', modify_after_accept: '通过后修改', publish: '发布计划', auto_filing: '自动备案', archive: '完成归档', assign_teacher: '分配指导教师', assign_teachers: '分配指导教师', assign_students: '分配学生', confirm_teacher: '教师确认', confirm_member: '成员确认', sign_in: '完成 GPS 签到' }[action] || action || '流程处理'; }
/** 读取某条流程记录的审核支线。 */
function reviewsFor(recordingId) { return (state.timeline.reviews || []).filter(item => Number(item.recording_id) === Number(recordingId)); }
/** 返回团队成员确认状态。 */
function confirmStatusText(status) { return { pending: '待确认', accepted: '已确认', refused: '已拒绝', rejected: '已拒绝' }[status] || status || '-'; }
/** 二次确认提交审核。 */
async function confirmSubmit(row) { try { await showConfirmDialog({ title: '提交审核', message: '提交后将进入审核流程，是否继续？' }); state.saving = true; await submitSocialPractice({ resource: actionResource(row), id: row.id }); showToast('已提交审核'); await loadList(1); } catch (error) { if (error !== 'cancel' && error !== 'close') showToast(error.message || String(error)); } finally { state.saving = false; } }
/** 返回当前记录操作按钮。 */
function rowActions(row) { const resource = actionResource(row); const actions = [{ key: 'view', label: '查看' }]; if (workflowResources.includes(resource)) actions.push({ key: 'timeline', label: '记录' }); if (resource === 'project' && isStudent.value && ['enabled', 'active'].includes(String(row.status))) actions.push({ key: 'signIn', label: '签到' }); if (isStudent.value && resource === 'declaration' && row.status === 'wait' && row.teacher_confirm_status === 'refused') actions.push({ key: 'teacherReselect', label: '重新选导师' }); if ((['draft', 'modify'].includes(row.status) || resource === 'project') && ['plan', 'project', 'implementation', 'declaration', 'material', 'patch_sign', 'score'].includes(resource) && canEditResource(resource)) actions.push({ key: 'edit', label: '修改' }); if (['draft', 'modify'].includes(row.status) && ['plan', 'implementation', 'declaration'].includes(resource)) actions.push({ key: 'submit', label: '提交审核' }); if (row.status === 'wait' && canReviewResource(resource) && (resource !== 'declaration' || row.teacher_confirm_status === 'accepted')) actions.push({ key: 'review', label: '审核' }); if (row.status === 'accept' && canReviewResource(resource)) actions.push({ key: 'modify', label: '通过后修改' }); if (resource === 'declaration' && isAdmin.value && props.hasPermission('social_practice:project:manage') && ['draft', 'wait', 'modify'].includes(row.status)) actions.push({ key: 'assignTeacher', label: '分配教师' }); if (resource === 'declaration' && isTeacher.value && ['pending', ''].includes(row.teacher_confirm_status) && Number(row.assigned_teacher_id || row.selected_teacher_id) > 0) actions.push({ key: 'teacherConfirm', label: '确认指导' }); return actions; }
/** 返回记录标题。 */
function rowTitle(row) { return row.title || row.project_title || row.plan_title || row.student_name || row.teacher_name || `记录 ${row.id}`; }
/** 返回记录副标题。 */
function rowSubtitle(row) { return [row.grade_name, row.dep_name, row.profession_name].filter(Boolean).join(' / '); }
/** 返回卡片摘要。 */
function rowFacts(row) { return [['实践项目', row.project_title], ['学生', row.student_name || row.applicant_name], ['指导教师', row.teacher_name || row.assigned_teacher_name || row.selected_teacher_name], ['地点', row.location], ['签到日期', row.date || row.sign_date], ['总评', row.final_score]].filter(([, value]) => value !== undefined && value !== null && value !== '').map(([label, value]) => `${label}：${value}`); }
/** 返回状态中文名。 */
function statusText(value) { return { draft: '草稿', wait: '待审核', accept: '已通过', modify: '需修改', enabled: '正常', active: '进行中', archived: '已归档', pending: '待确认', accepted: '已确认', refused: '已拒绝', rejected: '已拒绝' }[value] || value || '-'; }
/** 返回计划阶段名称。 */
function phaseText(value) { return { ready: '待发布', enrolling: '报名与分配', active: '实践进行中', scoring: '成果与评分', archived: '已归档' }[value] || value || '-'; }
