function factLabel(key) { return { title: '名称', plan_title: '所属计划', project_title: '实践项目', grade_name: '年级', student_name: '学生', applicant_name: '申报学生', teacher_name: '指导教师', assigned_teacher_name: '分配教师', location: '地点', declaration_type: '申报类型', teacher_confirm_status: '教师确认', date: '签到日期', sign_time: '签到时间', sign_date: '补签日期', final_score: '总评', version: '版本', status: '状态', created_at: '创建时间', updated_at: '更新时间' }[key] || key; }
