const workflowResources = ['plan', 'project', 'implementation', 'declaration', 'material', 'patch_sign', 'score'];
const defaultRequirements = () => materialTypes.map(item => ({ practice_mode: ['practice_proof', 'social_practice_report'].includes(item.value) ? 'distributed' : ['practice_report', 'practice_photo'].includes(item.value) ? 'centralized' : 'all', requirement_type: item.value, required_flag: item.value !== 'parent_notice', submit_scope: item.value === 'emergency_plan' ? 'project' : 'student' }));
